function get(id,lang){if(!cases[id])throw Error('Missing use case: '+id);return cases[id][lang==='ko'?0:1];}
function validate(data){if(Object.keys(cases).length!==data.items.length)throw Error('Use case coverage mismatch');for(const item of data.items)for(const lang of ['ko','en'])if(!get(item.id,lang))throw Error('Empty use case');}
module.exports={get,validate};
